1	import { useState, useMemo, useEffect, useRef, useCallback } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import { supabase } from '@/integrations/supabase/client';
4	import { toast } from 'sonner';
5	import {
6	  BookOpen, Plus, Search, Pencil, Trash2, ChevronDown,
7	  CheckCircle2, Clock, Archive, Eye, ChefHat, Layers,
8	  GripVertical, X, Calculator, Leaf, Image as ImageIcon, Camera, Loader2,
9	  Network, Workflow,
10	} from 'lucide-react';
11	import { cn } from '@/shared/lib/utils';
12	import { Badge } from '@/shared/ui/badge';
13	import { Button } from '@/shared/ui/button';
14	import { Input } from '@/shared/ui/input';
15	import { Label } from '@/shared/ui/label';
16	import { Textarea } from '@/shared/ui/textarea';
17	import {
18	  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter,
19	} from '@/shared/ui/dialog';
20	import {
21	  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
22	  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
23	} from '@/shared/ui/alert-dialog';
24	import {
25	  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
26	} from '@/shared/ui/select';
27	import {
28	  DropdownMenu, DropdownMenuContent, DropdownMenuItem,
29	  DropdownMenuSeparator, DropdownMenuTrigger,
30	} from '@/shared/ui/dropdown-menu';
31	import {
32	  Tabs, TabsContent, TabsList, TabsTrigger,
33	} from '@/shared/ui/tabs';
34	import {
35	  useFichasTecnicas, FichaForm, FichaTecnica, FichaItemForm, FichaEtapaForm, StatusFicha,
36	  custoItemFicha, calcularCustoFicha, CustoFichaRef,
37	} from '@/hooks/producao/useFichasTecnicas';
38	import { useInsumos, UNIDADES_PRODUCAO, Insumo } from '@/hooks/producao/useInsumos';
39	import { useMiaFichasTecnicasActions } from '@/features/mia/model/hooks';
40	
41	/* ─── helpers ─────────────────────────────────────────────── */
42	const STATUS_CONFIG: Record<StatusFicha, { label: string; icon: typeof CheckCircle2; className: string }> = {
43	  rascunho: { label: 'Rascunho', icon: Clock, className: 'bg-gray-100 text-gray-700 dark:bg-gray-800 dark:text-gray-300' },
44	  aprovada: { label: 'Aprovada', icon: CheckCircle2, className: 'bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-300' },
45	  obsoleta: { label: 'Obsoleta', icon: Archive, className: 'bg-gray-100 text-gray-500 dark:bg-gray-800 dark:text-gray-500' },
46	};
47	
48	const fmt = (n: number, dec = 2) =>
49	  n.toLocaleString('pt-BR', { minimumFractionDigits: dec, maximumFractionDigits: dec });
50	
51	const FORM_DEFAULT: FichaForm = {
52	  produto_master_id: null,
53	  nome: '',
54	  status: 'rascunho',
55	  rendimento_quantidade: 1,
56	  rendimento_unidade: 'un',
57	  fator_rendimento: 1.0,
58	  tempo_preparo_min: null,
59	  observacoes: '',
60	  itens: [],
61	  etapas: [],
62	};
63	
64	const ITEM_DEFAULT: FichaItemForm = {
65	  tipo: 'insumo',
66	  insumo_id: null,
67	  produto_master_id: null,
68	  sub_ficha_id: null,
69	  quantidade: 0,
70	  unidade: 'g',
71	  observacao: '',
72	  preco_unitario_esboco: null,
73	};
74	
75	type ItemKind = 'insumo' | 'sub_receita' | 'esboco' | 'produto';
76	
77	const itemKind = (it: FichaItemForm): ItemKind =>
78	  it.insumo_id != null ? 'insumo'
79	  : it.sub_ficha_id != null ? 'sub_receita'
80	  : it.produto_master_id != null ? 'produto'
81	  : 'esboco';
82	
83	const ETAPA_DEFAULT: FichaEtapaForm = {
84	  nome: '',
85	  setor: '',
86	  duracao_min: null,
87	  temperatura_c: null,
88	  instrucoes: '',
89	};
90	
91	/* ─── Modal ────────────────────────────────────────────────── */
92	function FichaModal({
93	  open, onClose, initial, initialPhotoUrl, onSave, onFormReady, insumos, fichas, currentFichaId,
94	}: {
95	  open: boolean;
96	  onClose: () => void;
97	  initial: FichaForm | null;
98	  initialPhotoUrl?: string | null;
99	  onSave: (f: FichaForm) => Promise<boolean>;
100	  onFormReady?: (setter: React.Dispatch<React.SetStateAction<FichaForm>> | null) => void;
101	  insumos: Insumo[];
102	  fichas: FichaTecnica[];
103	  currentFichaId: number | null;
104	}) {
105	  const [form, setForm] = useState<FichaForm>(initial ?? FORM_DEFAULT);
106	  const [saving, setSaving] = useState(false);
107	  const [tab, setTab] = useState('geral');
108	  const [produtosMaster, setProdutosMaster] = useState<{id: number, nome: string, preco_custo: number | null}[]>([]);
109	
110	  /** Sub-receitas disponíveis = outras fichas (não a que está sendo editada) */
111	  const subReceitaOpcoes = useMemo(
112	    () => fichas.filter((f) => f.id !== currentFichaId),
113	    [fichas, currentFichaId],
114	  );
115	  /** Referência de custo das fichas p/ custear sub-receitas consumidas */
116	  const fichasRef = useMemo<CustoFichaRef[]>(
117	    () => fichas.map((f) => ({
118	      id: f.id,
119	      custo_calculado: f.custo_calculado,
120	      rendimento_quantidade: f.rendimento_quantidade,
121	    })),
122	    [fichas],
123	  );
124	
125	  // Expose setForm to parent for MIA integration
126	  useEffect(() => {
127	    if (open) onFormReady?.(setForm);
128	    else onFormReady?.(null);
129	    return () => onFormReady?.(null);
130	  }, [open, onFormReady]);
131	
132	  useEffect(() => {
133	    if (open) {
134	      supabase.from('produtos_master').select('id, nome, preco_custo').eq('ativo', true).order('nome')
135	        .then(({ data }) => setProdutosMaster(data || []));
136	    }
137	  }, [open]);
138	
139	  const set = <K extends keyof FichaForm>(k: K, v: FichaForm[K]) =>
140	    setForm((p) => ({ ...p, [k]: v }));
141	
142	  /* Itens */
143	  const addItem = () => set('itens', [...form.itens, { ...ITEM_DEFAULT }]);
144	  const removeItem = (idx: number) => set('itens', form.itens.filter((_, i) => i !== idx));
145	  const setItem = <K extends keyof FichaItemForm>(idx: number, k: K, v: FichaItemForm[K]) =>
146	    set('itens', form.itens.map((it, i) => i === idx ? { ...it, [k]: v } : it));
147	
148	  /** Troca o tipo de um ingrediente, limpando atrelamentos incompatíveis */
149	  const setItemKind = (idx: number, kind: ItemKind) =>
150	    set('itens', form.itens.map((it, i) => {
151	      if (i !== idx) return it;
152	      return {
153	        ...it,
154	        tipo: kind === 'sub_receita' ? 'sub_receita' : 'insumo',
155	        insumo_id: null,
156	        sub_ficha_id: null,
157	        produto_master_id: null,
158	        observacao: kind === 'esboco' ? it.observacao : '',
159	        preco_unitario_esboco: kind === 'esboco' ? it.preco_unitario_esboco : null,
160	      };
161	    }));
162	
163	  /** Seleciona um insumo real numa linha (define unidade de produção padrão) */
164	  const pickInsumo = (idx: number, insumoId: number) => {
165	    const ins = insumos.find((i) => i.id === insumoId);
166	    set('itens', form.itens.map((it, i) => i === idx ? {
167	      ...it,
168	      tipo: 'insumo',
169	      insumo_id: insumoId,
170	      sub_ficha_id: null,
171	      produto_master_id: null,
172	      unidade: ins?.unidade_producao || it.unidade,
173	    } : it));
174	  };
175	
176	  /* Etapas */
177	  const addEtapa = () => set('etapas', [...form.etapas, { ...ETAPA_DEFAULT }]);
178	  const removeEtapa = (idx: number) => set('etapas', form.etapas.filter((_, i) => i !== idx));
179	  const setEtapa = <K extends keyof FichaEtapaForm>(idx: number, k: K, v: FichaEtapaForm[K]) =>
180	    set('etapas', form.etapas.map((et, i) => i === idx ? { ...et, [k]: v } : et));
181	
182	  /* Custo calculado — mesma lógica da gravação (insumo / sub-receita / esboço) */
183	  const custoTotal = useMemo(
184	    () => calcularCustoFicha(form.itens, insumos, fichasRef),
185	    [form.itens, insumos, fichasRef],
186	  );
187	
188	  const custoUnitario = form.rendimento_quantidade > 0
189	    ? custoTotal / form.rendimento_quantidade * form.fator_rendimento
190	    : 0;
191	
192	  const handleOpenChange = (isOpen: boolean) => {
193	    if (isOpen) { setForm(initial ?? FORM_DEFAULT); setTab('geral'); }
194	    if (!isOpen) onClose();
195	  };
196	
197	  const handleSave = async () => {
198	    if (!form.nome.trim()) return;
199	    setSaving(true);
200	    const ok = await onSave(form);
201	    setSaving(false);
202	    if (ok) onClose();
203	  };
204	
205	  return (
206	    <Dialog open={open} onOpenChange={handleOpenChange}>
207	      <DialogContent className={`${initialPhotoUrl ? 'max-w-[90vw]' : 'max-w-3xl'} max-h-[92vh] flex flex-col`}>
208	        <DialogHeader>
209	          <DialogTitle>{initial ? 'Editar Ficha Técnica' : 'Nova Ficha Técnica'}</DialogTitle>
210	        </DialogHeader>
211	
212	        <div className={`flex flex-1 overflow-hidden ${initialPhotoUrl ? 'gap-6' : ''}`}>
213	          {initialPhotoUrl && (
214	            <div className="hidden lg:flex flex-col w-1/2 rounded-xl overflow-hidden border border-border bg-black/5 dark:bg-black/40 relative">
215	               <img src={initialPhotoUrl} alt="Receita" className="object-contain w-full h-full" />
216	               <div className="absolute top-2 left-2 bg-black/60 text-white text-xs px-2 py-1 rounded-full backdrop-blur-md">
217	                 Imagem da Receita
218	               </div>
219	            </div>
220	          )}
221	
222	          <div className="flex-1 flex flex-col overflow-hidden min-w-0">
223	            <Tabs value={tab} onValueChange={setTab} className="flex-1 overflow-hidden flex flex-col">
224	              <TabsList className="shrink-0 w-max">
225	            <TabsTrigger value="geral">Geral</TabsTrigger>
226	            <TabsTrigger value="ingredientes">
227	              Ingredientes
228	              {form.itens.length > 0 && (
229	                <span className="ml-1.5 rounded-full bg-primary/20 px-1.5 text-[10px]">{form.itens.length}</span>
230	              )}
231	            </TabsTrigger>
232	            <TabsTrigger value="roteiro">
233	              Roteiro
234	              {form.etapas.length > 0 && (
235	                <span className="ml-1.5 rounded-full bg-primary/20 px-1.5 text-[10px]">{form.etapas.length}</span>
236	              )}
237	            </TabsTrigger>
238	          </TabsList>
239	
240	          <div className="flex-1 overflow-y-auto py-3">
241	            {/* TAB GERAL */}
242	            <TabsContent value="geral" className="mt-0 space-y-4">
243	              <div className="space-y-1">
244	                <Label>Atrelar Produto Final (Master)</Label>
245	                <Select
246	                  value={form.produto_master_id?.toString() || 'none'}
247	                  onValueChange={(v) => {
248	                    const id = v === 'none' ? null : Number(v);
249	                    set('produto_master_id', id);
250	                    if (id && !form.nome) {
251	                      const prod = produtosMaster.find(p => p.id === id);
252	                      if (prod) set('nome', prod.nome);
253	                    }
254	                  }}
255	                >
256	                  <SelectTrigger>
257	                    <SelectValue placeholder="Selecione o produto final no estoque..." />
258	                  </SelectTrigger>
259	                  <SelectContent>
260	                    <SelectItem value="none">Nenhum</SelectItem>
261	                    {produtosMaster.map(p => (
262	                      <SelectItem key={p.id} value={p.id.toString()}>{p.nome}</SelectItem>
263	                    ))}
264	                  </SelectContent>
265	                </Select>
266	                <p className="text-[11px] text-muted-foreground mt-1">O produto final (receita) que aumentará em estoque ao ser produzido.</p>
267	              </div>
268	
269	              <div className="space-y-1">
270	                <Label>Nome da Ficha *</Label>
271	                <Input data-mia-field="item"
272	                  placeholder="Ex: Bolo de Chocolate Recheado"
273	                  value={form.nome}
274	                  onChange={(e) => set('nome', e.target.value)}
275	                />
276	              </div>
277	
278	              <div className="grid grid-cols-2 gap-3">
279	                <div className="space-y-1">
280	                  <Label>Status</Label>
281	                  <Select value={form.status} onValueChange={(v) => set('status', v as StatusFicha)}>
282	                    <SelectTrigger><SelectValue /></SelectTrigger>
283	                    <SelectContent>
284	                      <SelectItem value="rascunho">Rascunho</SelectItem>
285	                      <SelectItem value="aprovada">Aprovada</SelectItem>
286	                      <SelectItem value="obsoleta">Obsoleta</SelectItem>
287	                    </SelectContent>
288	                  </Select>
289	                </div>
290	                <div className="space-y-1">
291	                  <Label>Tempo de Preparo (min)</Label>
292	                  <Input
293	                    type="number" min={0}
294	                    placeholder="Ex: 90"
295	                    value={form.tempo_preparo_min ?? ''}
296	                    onChange={(e) => set('tempo_preparo_min', e.target.value ? Number(e.target.value) : null)}
297	                  />
298	                </div>
299	              </div>
300	
301	              <div className="grid grid-cols-3 gap-3">
302	                <div className="space-y-1">
303	                  <Label>Rendimento (quantidade)</Label>
304	                  <Input
305	                    type="number" min={0} step="0.01"
306	                    value={form.rendimento_quantidade}
307	                    onChange={(e) => set('rendimento_quantidade', Number(e.target.value))}
308	                  />
309	                </div>
310	                <div className="space-y-1">
311	                  <Label>Unidade do Rendimento</Label>
312	                  <Select value={form.rendimento_unidade} onValueChange={(v) => set('rendimento_unidade', v)}>
313	                    <SelectTrigger><SelectValue /></SelectTrigger>
314	                    <SelectContent>
315	                      {['un', 'kg', 'g', 'dz', 'L', 'mL', 'porção'].map((u) => (
316	                        <SelectItem key={u} value={u}>{u}</SelectItem>
317	                      ))}
318	                    </SelectContent>
319	                  </Select>
320	                </div>
321	                <div className="space-y-1">
322	                  <Label>Fator de Rendimento</Label>
323	                  <Input
324	                    type="number" min={0} max={1} step="0.01"
325	                    value={form.fator_rendimento}
326	                    onChange={(e) => set('fator_rendimento', Number(e.target.value))}
327	                  />
328	                  <p className="text-[10px] text-muted-foreground">
329	                    {((1 - form.fator_rendimento) * 100).toFixed(0)}% de perda
330	                  </p>
331	                </div>
332	              </div>
333	
334	              <div className="space-y-1">
335	                <Label>Observações / Modo de Preparo</Label>
336	                <Textarea data-mia-field="item"
337	                  placeholder="Instruções gerais, dicas, padrões..."
338	                  value={form.observacoes}
339	                  onChange={(e) => set('observacoes', e.target.value)}
340	                  rows={3}
341	                />
342	              </div>
343	            </TabsContent>
344	
345	            {/* TAB INGREDIENTES */}
346	            <TabsContent value="ingredientes" className="mt-0 space-y-3">
347	              <div className="flex items-center justify-between">
348	                <p className="text-sm text-muted-foreground">
349	                  {form.itens.length === 0
350	                    ? 'Adicione os ingredientes desta receita.'
351	                    : `${form.itens.length} ingrediente(s)`}
352	                </p>
353	                <Button data-mia-action="add-item" size="sm" variant="outline" onClick={addItem}>
354	                  <Plus className="mr-1.5 h-3.5 w-3.5" />
355	                  Adicionar
356	                </Button>
357	              </div>
358	
359	              {form.itens.map((item, idx) => {
360	                const kind = itemKind(item);
361	                const produtoLegado = item.produto_master_id
362	                  ? produtosMaster.find((p) => p.id === item.produto_master_id)
363	                  : null;
364	                const custoItem = custoItemFicha(item, insumos, fichasRef);
365	                const kindBtn = (k: ItemKind, label: string, Icon: typeof Leaf, active: string) => (
366	                  <button
367	                    type="button"
368	                    data-mia-action={`item-tipo-${k}`}
369	                    onClick={() => setItemKind(idx, k)}
370	                    className={cn(
371	                      'flex-1 flex items-center justify-center gap-1 rounded-md border px-2 py-1 text-[11px] font-medium transition-colors',
372	                      kind === k ? active : 'border-border text-muted-foreground hover:text-foreground',
373	                    )}
374	                  >
375	                    <Icon className="h-3 w-3" />
376	                    {label}
377	                  </button>
378	                );
379	
380	                return (
381	                  <div key={idx} className="rounded-lg border border-border p-3 space-y-2">
382	                    <div className="flex items-start gap-2">
383	                      <GripVertical className="h-4 w-4 text-muted-foreground mt-1.5 shrink-0" />
384	                      <div className="flex-1 space-y-2 min-w-0">
385	                        {/* Seletor de tipo */}
386	                        <div className="flex gap-1">
387	                          {kindBtn('insumo', 'Insumo', Leaf, 'border-violet-400 bg-violet-50 text-violet-700 dark:bg-violet-950/40 dark:text-violet-300')}
388	                          {kindBtn('sub_receita', 'Sub-receita', ChefHat, 'border-amber-400 bg-amber-50 text-amber-700 dark:bg-amber-950/40 dark:text-amber-300')}
389	                          {kindBtn('esboco', 'Esboço', Pencil, 'border-orange-400 bg-orange-50 text-orange-700 dark:bg-orange-950/40 dark:text-orange-300')}
390	                        </div>
391	
392	                        {/* Origem do ingrediente conforme tipo */}
393	                        {kind === 'insumo' && (
394	                          <Select
395	                            value={item.insumo_id?.toString() ?? ''}
396	                            onValueChange={(v) => pickInsumo(idx, Number(v))}
397	                          >
398	                            <SelectTrigger data-mia-filter="item_insumo" className="h-8 text-xs">
399	                              <SelectValue placeholder="Selecione o insumo..." />
400	                            </SelectTrigger>
401	                            <SelectContent>
402	                              {insumos.length === 0 && (
403	                                <div className="px-2 py-1.5 text-xs text-muted-foreground">Nenhum insumo cadastrado.</div>
404	                              )}
405	                              {insumos.map((ins) => (
406	                                <SelectItem key={ins.id} value={ins.id.toString()}>{ins.nome}</SelectItem>
407	                              ))}
408	                            </SelectContent>
409	                          </Select>
410	                        )}
411	
412	                        {kind === 'sub_receita' && (
413	                          <Select
414	                            value={item.sub_ficha_id?.toString() ?? ''}
415	                            onValueChange={(v) => setItem(idx, 'sub_ficha_id', Number(v))}
416	                          >
417	                            <SelectTrigger data-mia-filter="item_sub_receita" className="h-8 text-xs">
418	                              <SelectValue placeholder="Selecione a sub-receita..." />
419	                            </SelectTrigger>
420	                            <SelectContent>
421	                              {subReceitaOpcoes.length === 0 && (
422	                                <div className="px-2 py-1.5 text-xs text-muted-foreground">Nenhuma outra ficha disponível.</div>
423	                              )}
424	                              {subReceitaOpcoes.map((f) => (
425	                                <SelectItem key={f.id} value={f.id.toString()}>{f.nome}</SelectItem>
426	                              ))}
427	                            </SelectContent>
428	                          </Select>
429	                        )}
430	
431	                        {kind === 'esboco' && (
432	                          <div className="grid grid-cols-2 gap-2">
433	                            <Input data-mia-field="item"
434	                              className="h-8 text-xs"
435	                              placeholder="Nome livre (ex: Pasta de Pistache)"
436	                              value={item.observacao}
437	                              onChange={(e) => setItem(idx, 'observacao', e.target.value)}
438	                            />
439	                            <Input data-mia-field="item"
440	                              type="number" min={0} step="0.0001"
441	                              className="h-8 text-xs"
442	                              placeholder={`R$/${item.unidade} (opcional)`}
443	                              value={item.preco_unitario_esboco ?? ''}
444	                              onChange={(e) => setItem(idx, 'preco_unitario_esboco', e.target.value ? Number(e.target.value) : null)}
445	                            />
446	                          </div>
447	                        )}
448	
449	                        {kind === 'produto' && (
450	                          <div className="flex items-center gap-2 rounded-md border border-dashed border-border px-2 py-1.5 text-xs">
451	                            <span className="truncate">{produtoLegado?.nome ?? `Produto #${item.produto_master_id}`}</span>
452	                            <span className="ml-auto text-[10px] text-muted-foreground">item legado — troque o tipo p/ atualizar</span>
453	                          </div>
454	                        )}
455	
456	                        {/* Quantidade + Unidade */}
457	                        <div className="grid grid-cols-2 gap-2">
458	                          <div className="space-y-1">
459	                            <Label className="text-xs">Quantidade</Label>
460	                            <Input data-mia-field="item"
461	                              type="number" min={0} step="0.01"
462	                              className="h-8 text-xs"
463	                              value={item.quantidade || ''}
464	                              onChange={(e) => setItem(idx, 'quantidade', e.target.value ? Number(e.target.value) : 0)}
465	                            />
466	                          </div>
467	                          <div className="space-y-1">
468	                            <Label className="text-xs">Unidade</Label>
469	                            <Select
470	                              value={item.unidade}
471	                              onValueChange={(v) => setItem(idx, 'unidade', v)}
472	                            >
473	                              <SelectTrigger className="h-8 text-xs"><SelectValue /></SelectTrigger>
474	                              <SelectContent>
475	                                {UNIDADES_PRODUCAO.map((u) => (
476	                                  <SelectItem key={u.value} value={u.value}>{u.label}</SelectItem>
477	                                ))}
478	                              </SelectContent>
479	                            </Select>
480	                          </div>
481	                        </div>
482	                      </div>
483	
484	                      <button onClick={() => removeItem(idx)} className="mt-1.5 text-muted-foreground hover:text-destructive">
485	                        <X className="h-4 w-4" />
486	                      </button>
487	                    </div>
488	
489	                    {custoItem > 0 && (
490	                      <div className="ml-6 text-xs text-muted-foreground flex items-center gap-2">
