78	  if (idx < 0) return null;
79	  const type = key.slice(0, idx);
80	  const id = Number(key.slice(idx + 1));
81	  if (!Number.isFinite(id)) return null;
82	  if (type === 'ficha') return { type: 'ficha', id };
83	  if (type === 'produto') return { type: 'produto_master', id };
84	  if (type === 'insumo') return { type: 'insumo', id };
85	  if (type === 'nf') return { type: 'nf', id };
86	  if (type === 'item') return { type: 'item', id };
87	  return null;
