48	
49	    op_fill_create: {
50	      id: 'op_fill_create',
51	      description: 'Preencher formulário de nova OP (ficha, quantidade, data, tipo)',
52	      execute: async (data) => {
53	        if (!data) return;
54	        // Open modal first
55	        setCriarOpen(true);
