70	          return next;
71	        });
72	      },
73	    },
74	
75	    op_fill_apontamento: {
76	      id: 'op_fill_apontamento',
77	      description: 'Preencher apontamento de produção (quantidade produzida, perdas)',
78	      execute: async (data) => {
79	        if (!data) return;
80	        // If an OP is specified, open its apontamento modal first
